const KEY='pawrescue-valencia-v1';
const samples=[{id:'sample-1',type:'Lost',name:'Luna',area:'Benimaclet',date:'2026-10-20',description:'Sample report: golden coat, medium size, green collar. This is a fictional dog used to demonstrate the platform.',color:'#c78e58',sample:true},{id:'sample-2',type:'Found',name:'A little explorer',area:'El Cabanyal',date:'2026-10-21',description:'Sample report: small cream dog with floppy ears. This is a fictional report; no dog is being held at this location.',color:'#d9c2a1',sample:true},{id:'sample-3',type:'Lost',name:'Bruno',area:'Russafa',date:'2026-10-22',description:'Sample report: dark coat, white chest, medium size. This is a fictional dog used to demonstrate a lost-dog report.',color:'#57514a',sample:true}];
let reports;try{reports=JSON.parse(localStorage.getItem(KEY))||structuredClone(samples);if(!Array.isArray(reports))throw Error();}catch{reports=structuredClone(samples)}
let filter='all';const $=s=>document.querySelector(s);const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function dog(color){return `<svg viewBox="0 0 220 180" aria-hidden="true"><ellipse cx="110" cy="165" rx="66" ry="7" fill="#0000000b"/><path d="M69 110 Q43 77 64 46 L77 64 Q109 44 142 65 L157 46 Q182 85 151 114 L149 162 L127 162 L120 128 L98 128 L92 162 L70 162Z" fill="${color}"/><path d="M64 46 Q42 40 40 83 Q51 111 72 85 M157 46 Q179 37 181 84 Q173 112 150 85" fill="${color}" stroke="#00000012" stroke-width="5"/><ellipse cx="110" cy="105" rx="29" ry="24" fill="#f3e4cd"/><ellipse cx="110" cy="98" rx="10" ry="7" fill="#2c342b"/><circle cx="84" cy="82" r="4" fill="#29352b"/><circle cx="136" cy="82" r="4" fill="#29352b"/><path d="M110 105 v8 m-12 0 q12 12 24 0" fill="none" stroke="#29352b" stroke-width="2"/><path d="M73 124 Q110 141 149 124" fill="none" stroke="#68785c" stroke-width="7"/><circle cx="110" cy="138" r="6" fill="#e8b659"/></svg>`}
function save(){localStorage.setItem(KEY,JSON.stringify(reports))}
function render(){const q=$('#search').value.toLowerCase();const list=reports.filter(r=>(filter==='all'||r.type===filter)&&(r.name+' '+r.area).toLowerCase().includes(q));$('#cards').innerHTML=list.length?list.map(r=>`<article class="card"><div class="dog-picture">${r.photo?`<img src="${r.photo}" alt="Photo for ${escapeHTML(r.name)}">`:dog(r.color||'#ba8b65')}<span class="status ${r.type==='Found'?'found':''}">${escapeHTML(r.type)}</span></div><div class="card-body"><h3>${escapeHTML(r.name)}</h3><div class="meta">◎ ${escapeHTML(r.area)} · Valencia</div><div class="card-bottom"><span class="sample">${r.sample?'Example report':'On this device'} · ${escapeHTML(r.date)}</span><button class="textlink" data-detail="${escapeHTML(r.id)}" aria-label="View report for ${escapeHTML(r.name)}">View →</button></div></div></article>`).join(''):'<p class="empty">No matching reports. Try another area or report type.</p>'}
function info(title,html){$('#info-title').textContent=title;$('#info-body').innerHTML=html;$('#info-dialog').showModal()}
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{$('#report-form').reset();$('#form-error').textContent='';const date=$('[name=date]');date.value=new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Madrid'});$('#report-dialog').showModal()});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});render()});$('#search').oninput=render;
$('#cards').onclick=e=>{const b=e.target.closest('[data-detail]');if(!b)return;const r=reports.find(x=>x.id===b.dataset.detail);info(r.name,`${r.photo?`<img class="detail-photo" src="${r.photo}" alt="Dog report photo">`:''}<p><strong>${escapeHTML(r.type)} · ${escapeHTML(r.area)}, Valencia</strong><br>${escapeHTML(r.date)}</p><p>${escapeHTML(r.description)}</p><p class="muted">${r.sample?'Fictional example. There is no real owner or finder to contact.':'Private browser demo. This report has not been shared with anyone.'}</p>${!r.sample?`<button class="button" id="resolve">Mark as reunited</button>`:''}`);if(!r.sample)$('#resolve').onclick=()=>{reports=reports.filter(x=>x.id!==r.id);try{save();render();$('#info-dialog').close()}catch{info('Unable to save','<p>Your browser storage is unavailable. Please try again.</p>')}}};
$('#report-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target);const photo=data.get('photo');$('#form-error').textContent='';let image='';if(photo?.size){if(photo.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(photo.type)){$('#form-error').textContent='Choose a JPEG, PNG or WebP image smaller than 2 MB.';return}image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(photo)})}const item={id:crypto.randomUUID(),type:data.get('type'),name:data.get('name').trim(),area:data.get('area').trim(),date:data.get('date'),description:data.get('description').trim(),photo:image};if(!item.name||!item.area||!item.description){$('#form-error').textContent='Please complete all required text fields.';return}reports.unshift(item);try{save()}catch{reports.shift();$('#form-error').textContent='Could not save. Browser storage may be full; try a smaller photo.';return}filter='all';$('#search').value='';document.querySelector('[data-filter=all]').click();$('#report-dialog').close();$('#reports').scrollIntoView({behavior:'smooth'})};
$('#reset').onclick=()=>info('Reset this demo?','<p>This removes reports saved in this browser and restores the three fictional examples.</p><button class="button" id="confirm-reset">Reset local reports</button>');$('#info-dialog').addEventListener('click',e=>{if(e.target.id==='confirm-reset'){const old=reports;reports=structuredClone(samples);try{save();render();$('#info-dialog').close()}catch{reports=old;info('Unable to reset','<p>Browser storage is unavailable.</p>')}}});
$('#find-care').onclick=()=>{const city=$('#municipality').value;$('#care-title').textContent=city==='Valencia'?'No verified partners in Valencia yet':city+' is not active yet';$('#care-text').textContent=city==='Valencia'?'There are currently no participating places or confirmed capacity to recommend. This pilot does not provide live intake availability.':'This municipality is a future expansion option. No partner records or availability have been added.'};
$('#join').onclick=()=>info('Welcome, future partners.','<p>Partner registration is being designed. It will collect your organisation name, municipality, public contact details, location, opening hours and intake capacity.</p><p>Each organisation must be verified before it appears in search. Availability will include a last-confirmed time.</p><p><strong>No registration is submitted in this prototype.</strong></p>');
$('#donate').onclick=()=>info('Give with a clear destination.','<p>Donations are not enabled yet. We first need a verified beneficiary, a payment provider and a clear explanation of how funds will be used.</p><p>No money is collected by this prototype. Future donations can support a participating organisation or the network, with the recipient clearly identified before payment.</p>');
$('#about').onclick=()=>info('Local care. Shared code.','<p>PawRescue Network connects lost and found dog reports, participating care organisations and transparent donations. The English-language pilot starts in Valencia, Spain, and is designed to expand municipality by municipality.</p><p>This independent community prototype is not an official municipal service. Reports are local to your browser. There are no verified partners, public submissions, live capacity feeds or active payments yet.</p><p>The source includes an MIT license and contribution guidance for an open-source GitHub project.</p>');render();
